mapper.select:
select p.id as profileId, p.profile_type as profileType, p.gender, p.birth_year as birthYear, p.height, p.city_code as cityCode, (select lf.value from cm_profile_localized_fields lf where lf.profile_id = p.id and lf.field_name = 'profile_name' and lf.locale = 'zh' limit 1) as profileName, (select lf.value from cm_profile_localized_fields lf where lf.profile_id = p.id and lf.field_name = 'city' and lf.locale = 'zh' limit 1) as cityLabel, (select lf.value from cm_profile_localized_fields lf where lf.profile_id = p.id and lf.field_name = 'industry' and lf.locale = 'zh' limit 1) as industryLabel, (select lf.value from cm_profile_localized_fields lf where lf.profile_id = p.id and lf.field_name = 'career_direction' and lf.locale = 'zh' limit 1) as careerDirectionLabel, (select lf.value from cm_profile_localized_fields lf where lf.profile_id = p.id and lf.field_name = 'summary' and lf.locale = 'zh' limit 1) as summary, (select group_concat(li.value order by li.item_order separator '、') from cm_profile_localized_items li where li.profile_id = p.id and li.field_name = 'tags' and li.locale = 'zh') as tags, p.profile_status as profileStatus, p.updated_at as updatedAt, o.user_id as ownerUserId, u.account_name as ownerAccountName, (select count(1) from cm_profile_photos pp where pp.profile_id = p.id) as photoCount, (select count(1) from cm_profile_photos pp where pp.profile_id = p.id and pp.status = 'review') as photoReviewCount, ir.id as internalRecordId, coalesce(ir.is_featured, 0) as isFeatured, ir.updated_by_user_id as internalUpdatedByUserId, su.nick_name as internalUpdatedByName, ir.updated_at as internalUpdatedAt, (select count(distinct ilf.locale) from cm_profile_internal_localized_fields ilf where ilf.internal_record_id = ir.id and ilf.field_name = 'employer' and ilf.value != '') as employerLocaleCount, (select count(distinct ilf.locale) from cm_profile_internal_localized_fields ilf where ilf.internal_record_id = ir.id and ilf.field_name = 'income_range' and ilf.value != '') as incomeRangeLocaleCount, (select count(distinct ilf.locale) from cm_profile_internal_localized_fields ilf where ilf.internal_record_id = ir.id and ilf.field_name = 'staff_notes' and ilf.value != '') as staffNotesLocaleCount, (select ilf.value from cm_profile_internal_localized_fields ilf where ilf.internal_record_id = ir.id and ilf.field_name = 'employer' and ilf.locale = 'zh' limit 1) as employer, (select ilf.value from cm_profile_internal_localized_fields ilf where ilf.internal_record_id = ir.id and ilf.field_name = 'income_range' and ilf.locale = 'zh' limit 1) as incomeRange from cm_profiles p left join cm_profile_ownerships o on o.profile_id = p.id and o.status = 'active' left join cm_users u on u.id = o.user_id left join cm_profile_verifications v on v.profile_id = p.id left join cm_profile_internal_records ir on ir.profile_id = p.id left join sys_user su on cast(su.user_id as char) = ir.updated_by_user_id where p.archived_at is null and p.profile_status = 'open'
and coalesce(ir.is_featured, 0) = #{featured}
order by ir.updated_at desc, p.updated_at desc order by coalesce(ir.is_featured, 0) desc, p.updated_at desc order by profileName asc, p.updated_at desc order by ownerAccountName asc, p.updated_at desc order by p.updated_at desc

mapper.update:
update cm_profile_internal_localized_fields
set status = #{status}, updated_at = now()
where internal_record_id = #{internalRecordId}
  and field_name = #{fieldName}
  and locale = #{locale}
  and status = 'pending'

update cm_profiles
set profile_status = #{status}, updated_at = now()
where id = #{profileId}

update cm_profile_photos
set status = #{status}, updated_at = now()
where id = #{photoId}

mapper.sql:
p.profile_status in ('open', 'review')
and p.archived_at is null

    and not exists (
        select 1 from cm_profile_ownerships o
        where o.profile_id = p.id
          and o.user_id = #{viewerUserId}
          and o.status = 'active'
    )


    and p.gender = #{gender}


    and (year(now()) - p.birth_year) >= #{ageMin}


    and (year(now()) - p.birth_year) <= #{ageMax}


    and p.height >= #{heightMin}


    and p.height <= #{heightMax}


    and p.city_code = #{city}


    and p.education_code = #{education}


    and p.industry_code = #{industry}


    and exists (
        select 1 from cm_profile_languages l
        where l.profile_id = p.id and l.language_code = #{language}
    )


    and p.marital_status = #{maritalStatus}


    and p.has_children = #{hasChildrenFilter}


    and p.accepts_long_distance = #{acceptsLongDistanceFilter}


    and p.dating_intention_code = #{datingIntentionCode}


    and exists (
        select 1 from cm_profile_verifications v
        where v.profile_id = p.id
          and v.identity_status = 'verified'
          and v.review_status = 'approved'
    )


    and not exists (
        select 1 from cm_profile_verifications v
        where v.profile_id = p.id
          and v.identity_status = 'verified'
          and v.review_status = 'approved'
    )

p.family_visible = 1
and p.profile_status in ('open', 'review')
and p.archived_at is null

    and not exists (
        select 1 from cm_profile_ownerships o
        where o.profile_id = p.id
          and o.user_id = #{viewerUserId}
          and o.status = 'active'
    )


    and p.gender = #{gender}


    and (year(now()) - p.birth_year) >= #{ageMin}


    and (year(now()) - p.birth_year) <= #{ageMax}


    and p.city_code = #{city}


    and p.education_code = #{education}


    and p.industry_code = #{industry}


    and p.marital_status = #{maritalStatus}


    and p.has_children = #{hasChildrenFilter}


    and p.accepts_long_distance = #{acceptsLongDistanceFilter}


    and p.dating_intention_code = #{datingIntentionCode}


    and exists (
        select 1 from cm_profile_internal_records ir2
        where ir2.profile_id = p.id and ir2.is_featured = 1
    )

